<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute } from 'vue-router'
import { entries, knowledgeTerms } from '../data/demo'

const route = useRoute()
const entry = computed(() => entries.find(item => item.id === Number(route.params.id)) || entries[0])
const mode = ref<'split' | 'game' | 'real'>('split')
const saved = ref(entry.value.saved)
const activeTerm = ref('')
const answer = ref('')
const questions = ['这组悬塑为什么值得看？', '游戏画面做了哪些再创作？', '现场参观应该看哪里？']

function ask(question: string) {
  const replies: Record<string, string> = {
    '这组悬塑为什么值得看？': '它把大量独立塑像组织成连续的立体叙事。建议先看整体层次，再找主尊、胁侍与云气纹之间的关系。',
    '游戏画面做了哪些再创作？': '游戏强化了金色光源、纵深和戏剧冲突。现实殿内依赖自然采光，造像的空间秩序比画面特效更值得细看。',
    '现场参观应该看哪里？': '先在殿门附近适应暗光，再从中轴看整体构图，最后观察侧墙悬塑的前后遮挡。殿内不要使用闪光灯。',
  }
  answer.value = replies[question]
}
</script>

<template>
  <div class="detail-page">
    <header class="detail-heading"><router-link to="/">← 返回图鉴</router-link><div><span>小西天 · {{ entry.dynasty }}代 {{ entry.targetType }} · {{ entry.matchLevel }}</span><h1>{{ entry.title }}</h1><p>{{ entry.summary }}</p></div><button :class="{ saved }" @click="saved = !saved">{{ saved ? '已收藏' : '收藏条目' }}</button></header>
    <section class="compare-section">
      <div class="compare-toolbar"><span>双图对照</span><div><button :class="{active:mode==='split'}" @click="mode='split'">并排</button><button :class="{active:mode==='game'}" @click="mode='game'">游戏侧</button><button :class="{active:mode==='real'}" @click="mode='real'">现实侧</button></div></div>
      <div :class="['comparison',mode]"><figure v-if="mode!=='real'"><img :src="entry.images.game" alt="游戏画面演示占位"><figcaption><b>游戏画面</b><span>内部演示 placeholder · 待授权素材替换</span></figcaption></figure><figure v-if="mode!=='game'"><img :src="entry.images.real" alt="现实文物演示占位"><figcaption><b>现实文物</b><span>内部演示 placeholder · 待 CC/授权素材替换</span></figcaption></figure></div>
    </section>
    <main class="article-layout">
      <article>
        <section><span class="section-number">01</span><div><small>HOW TO READ</small><h2>游戏如何化用现实</h2><p>{{ entry.summary }}</p><blockquote>对照的重点不是“长得像”，而是看构图、造型和空间关系如何被重新组织。</blockquote></div></section>
        <section><span class="section-number">02</span><div><small>ARCHIVE</small><h2>文物档案</h2><dl><div><dt>现实文物</dt><dd>{{ entry.targetName }}</dd></div><div><dt>类型</dt><dd>{{ entry.targetType }}</dd></div><div><dt>年代</dt><dd>{{ entry.dynasty }}代（具体年代待正式内容核查）</dd></div><div><dt>所在地点</dt><dd>山西临汾隰县 · 小西天</dd></div></dl></div></section>
        <section><span class="section-number">03</span><div><small>DETAILS</small><h2>价值与看点</h2><ol><li v-for="point in entry.valuePoints" :key="point"><strong>{{ point }}</strong><p>从构件、造型与观看位置理解这一细节，现场观察会比单看照片更清楚。</p></li></ol><p class="term-links">相关术语：<button v-for="term in entry.terms" :key="term" @click="activeTerm=term">{{ term }}</button></p></div></section>
        <section class="sources"><span class="section-number">04</span><div><small>SOURCES</small><h2>信源与可信度</h2><div class="credibility"><strong>{{ entry.credibility }}%</strong><span>演示可信度</span><p>包含 {{ entry.sources.filter(s=>s.level==='S'||s.level==='A').length }} 个 S/A 级信源</p></div><div v-for="source in entry.sources" :key="source.title" class="source"><b>{{ source.level }}</b><div><strong>{{ source.title }}</strong><span>{{ source.type }} · 演示信源，正式发布前补全链接与引文</span></div></div></div></section>
      </article>
      <aside><router-link class="guide-link onsite" to="/onsite/14"><span>现场模式</span><strong>按区域找到对应物</strong><small>参照图 · 方向指引 · 辨认特征 →</small></router-link><div class="ai-card"><header><span>AI</span><div><strong>古建讲解助手</strong><small>演示版 · 预置知识卡片</small></div></header><p>关于这条对照，你想先看懂什么？</p><button v-for="question in questions" :key="question" @click="ask(question)">{{ question }}</button><div v-if="answer" class="answer"><b>讲解助手</b><p>{{ answer }}</p><small>回答来自预置知识卡片，不是实时大模型生成。</small></div></div><router-link class="guide-link" to="/location-guide"><span>实用信息</span><strong>小西天参观信息卡</strong><small>开放时间 · 预约 · 拍摄规定 →</small></router-link></aside>
    </main>
    <div v-if="activeTerm" class="term-modal" @click.self="activeTerm=''" role="dialog"><div><button @click="activeTerm=''">×</button><small>古建知识字典</small><h2>{{ activeTerm }}</h2><p>{{ knowledgeTerms.find(item=>item.term===activeTerm)?.definition || '该术语卡正在采编中。' }}</p><router-link :to="`/dictionary?term=${activeTerm}`">查看完整词条 →</router-link></div></div>
  </div>
</template>

